-- Synthetic PostgreSQL fixture only; no production data.
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.test_assert((select bool_and(commission_basis='revenue' and commission_terms_version=0) from public.partner_network_partners),'migration preserves legacy partner revenue terms');
select public.test_assert(not exists(select 1 from public.profit_test_paid_before b join public.partner_network_commissions c on c.id=b.id where
 (b.status,b.rate_percent,b.eligible_base,b.calculated_amount,b.paid_amount,b.paid_reference,b.paid_at,b.paid_by,b.fingerprint) is distinct from
 (c.status,c.rate_percent,c.eligible_base,c.calculated_amount,c.paid_amount,c.paid_reference,c.paid_at,c.paid_by,c.fingerprint)),'migration does not rewrite paid ledger or fingerprints');
select public.test_assert((select not public and file_size_limit=5242880 from storage.buckets where id='partner-cost-statements'),'private proof bucket configured with5MiB limit');
set role authenticated;
select public.test_error(format('select public.partner_network_manage_partner(%L,''update'',''{"commission_basis":"profit"}'')',current_setting('test.partner_a')),'commission_basis_reason_required');
select public.test_error(format('select public.partner_network_manage_partner(%L,''update'',''{"commission_basis":"invalid"}'')',current_setting('test.partner_a')),'invalid_commission_basis');
select public.partner_network_manage_partner(current_setting('test.partner_a')::uuid,'update','{"commission_basis":"profit","default_rate_percent":3,"first_order_rate_percent":3,"repeat_rate_percent":5,"repeat_order_limit":3,"reason":"Explicitly agreed commission on confirmed profit after all costs"}');
select public.test_assert(exists(select 1 from public.partner_network_audit where entity='partner_network_partners' and after_data->>'commission_basis'='profit' and length(after_data->>'review_reason')>=10),'basis change and explicit reason retained in durable audit');
select public.test_assert((select commission_basis='profit' and commission_terms_version=1 from public.partner_network_partners where id=current_setting('test.partner_a')::uuid),'explicit profit agreement versioned');
select public.test_assert((select (c->>'stale')::boolean from jsonb_array_elements(public.partner_network_admin_snapshot()->'commissions') c where c->>'order_id'='test-vnd-round'),'basis change invalidates existing unpaid approval/review');
select public.test_error($q$select public.partner_network_reconcile('test-vnd-round','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"minimum_retained_profit":100000,"review_note":"Missing explicit basis adoption"}')$q$,'commission_basis_reason_required');
select public.partner_network_reconcile('test-vnd-round','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"minimum_retained_profit":100000,"commission_basis":"profit","adjustment_reason":"Explicitly adopt changed profit agreement","review_note":"All actual costs confirmed"}');
select public.test_assert((select commission_basis='profit' and commission_base=487654 and calculated_amount=14630 from public.partner_network_commissions where order_id='test-vnd-round'),'unpaid explicit adoption computes3percent after actualcosts roundedwholeVND');
select public.test_error($q$select public.partner_network_reconcile('test-o1','{"vat_amount":100000,"billed_shipping_amount":50000,"refunded_amount":1000000,"internal_cost_total":200000,"minimum_retained_profit":100000,"commission_basis":"profit","adjustment_reason":"Attempt to change historical basis","review_note":"Paid old agreement remains unchanged"}')$q$,'paid_commission_immutable');
select public.test_assert((select (c->>'current_commission_basis')='revenue' from jsonb_array_elements(public.partner_network_admin_snapshot()->'commissions') c where c->>'order_id'='test-o1'),'paid old commission retains its original revenue basis');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.partner_network_submit_lead('{"request_id":"00000000-0000-4000-8000-000000000901","business_name":"Profit Test Cafe","contact_name":"Test owner","contact":"0905000901","location":"Test region","product_interest":"Hồng trà","contact_authorized":true}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000901','accept','{}');
reset role;
insert into public.trade_quotes(id,opportunity_id) values('profit-q','opp-referral-00000000-0000-4000-8000-000000000901');
insert into public.orders(id,ts,type,status,quote_id) values
 ('profit-o1',now()+interval '1 second','wholesale','confirmed','profit-q'),
 ('profit-o2',now()+interval '2 seconds','wholesale','confirmed','profit-q'),
 ('profit-unknown',now()+interval '3 seconds','wholesale','confirmed','profit-q'),
 ('profit-loss',now()+interval '4 seconds','wholesale','confirmed','profit-q'),
 ('profit-partial',now()+interval '5 seconds','wholesale','confirmed','profit-q');
insert into public.receivables values('profit-r1','profit-o1',1000000,1000000,'paid'),('profit-r2','profit-o2',1000000,1000000,'paid'),('profit-ru','profit-unknown',1000000,1000000,'paid'),('profit-rl','profit-loss',1000000,1000000,'paid'),('profit-rp','profit-partial',1000000,500000,'partial');
insert into public.receivable_payments(id,receivable_id,amount) values('profit-c1','profit-r1',1000000),('profit-c2','profit-r2',1000000),('profit-cu','profit-ru',1000000),('profit-cl','profit-rl',1000000),('profit-cp','profit-rp',500000);
set role authenticated;
select public.partner_network_reconcile('profit-o1','{"vat_amount":100000,"billed_shipping_amount":50000,"refunded_amount":50000,"internal_cost_total":600000,"minimum_retained_profit":100000,"review_note":"All production packing logistics and allocated operating costs confirmed"}');
select set_config('test.profit_c1',(select id::text from public.partner_network_commissions where order_id='profit-o1'),false);
select public.test_assert((select eligible_base=800000 and commission_base=200000 and calculated_amount=6000 and rate_percent=3 and commission_basis='profit' from public.partner_network_commissions where order_id='profit-o1'),'firstorder3percent applies to200k profit after VAT shippingrefund and allcosts, not800k revenue');
select public.partner_network_reconcile('profit-o2','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":400000,"minimum_retained_profit":100000,"review_note":"Repeat order allcosts confirmed"}');
select public.test_assert((select rate_percent=5 and commission_base=600000 and calculated_amount=30000 from public.partner_network_commissions where order_id='profit-o2'),'configured repeat5percent applies toprofit');
select public.partner_network_reconcile('profit-unknown','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"minimum_retained_profit":100000,"review_note":"Costs still unknown"}');
select public.test_assert((select commission_base is null and calculated_amount is null from public.partner_network_commissions where order_id='profit-unknown'),'unknowncosts persist unknownprofit calculation, not invented zero');
select public.test_error(format('select public.partner_network_commission_action(%L,''approve'',''{}'')',(select id from public.partner_network_commissions where order_id='profit-unknown')),'profit_review_required');
select public.test_error(format('select public.partner_network_commission_action(%L,''pay'',''{"amount":1,"reference":"blocked","paid_at":"2026-10-14"}'')',(select id from public.partner_network_commissions where order_id='profit-unknown')),'profit_review_required');
select public.partner_network_reconcile('profit-loss','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":2000000,"minimum_retained_profit":0,"review_note":"Confirmed loss afterallcosts"}');
select public.test_assert((select commission_base=0 and calculated_amount=0 from public.partner_network_commissions where order_id='profit-loss'),'loss order has zero commission');
select public.test_error(format('select public.partner_network_commission_action(%L,''adjust'',''{"adjustment_amount":1,"reason":"Cannot manufacture commission on loss"}'')',(select id from public.partner_network_commissions where order_id='profit-loss')),'no_eligible_revenue');
select public.partner_network_reconcile('profit-partial','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":100000,"minimum_retained_profit":100000,"rate_percent":3,"adjustment_reason":"Explicit test order negotiatedrate","review_note":"Only partialcash received, costsconfirmed"}');
select public.partner_network_commission_action((select id from public.partner_network_commissions where order_id='profit-partial'),'approve','{}');
select public.test_error(format('select public.partner_network_commission_action(%L,''pay'',''{"amount":12000,"reference":"incomplete","paid_at":"2026-10-14"}'')',(select id from public.partner_network_commissions where order_id='profit-partial')),'customer_payment_incomplete');
select public.test_error(format('select public.partner_network_cost_statement(%L,''publish'',''{"summary":"Not yet publishable","content_reviewed":true}'')','profit-unknown'),'profit_review_required');
select public.test_error($q$select public.partner_network_prepare_cost_evidence('profit-o1','bad/file.pdf','application/pdf',128)$q$,'invalid_cost_evidence');
select public.test_error($q$select public.partner_network_prepare_cost_evidence('profit-o1','too-big.pdf','application/pdf',5242881)$q$,'invalid_cost_evidence');
select public.test_error($q$select public.partner_network_prepare_cost_evidence('profit-o1','active.html','text/html',128)$q$,'invalid_cost_evidence');
select set_config('test.proof',(public.partner_network_prepare_cost_evidence('profit-o1','Reviewed-cost-summary.pdf','application/pdf',128)->>'id'),false);
select public.test_error(format('select public.partner_network_finalize_cost_evidence(%L,128)',current_setting('test.proof')),'cost_evidence_upload_unverified');
select public.test_error(format('select public.partner_network_cost_statement(''profit-o1'',''publish'',%L)',jsonb_build_object('summary','Reviewed summary','evidence_id',current_setting('test.proof'),'content_reviewed',true,'expected_snapshot',(public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->'preview_snapshot')-'order_id')::text),'ready_cost_evidence_required');
select public.test_assert((public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->'preview_snapshot'->>'internal_cost_total')::numeric=600000,'manager sees current safe preview before approving sharing');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert((public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->>'available')::boolean=false,'own partner has no automatic cost release');
select public.test_assert((select x->'eligible_base'='null'::jsonb and x->'commission_base'='null'::jsonb and x->'cost_statement'='null'::jsonb and (x->>'eligible_amount')::numeric=6000 from jsonb_array_elements(public.partner_network_snapshot()->'commissions')x where x->>'order_id'='profit-o1'),'own commission shown without unpublished profit/computation/costfields');
select public.test_assert((select count(*)=0 from public.partner_network_cost_evidence) and (select count(*)=0 from public.partner_network_cost_statements),'partner cannot directly read evidence or statement tables');
select public.test_error(format('select public.partner_network_cost_evidence_access(%L)',current_setting('test.proof')),'cost_evidence_not_available');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'partner-cost-statements',storage_path,'{"size":128,"mimetype":"application/pdf"}' from public.partner_network_cost_evidence where id=current_setting('test.proof')::uuid;
set role authenticated;
select public.partner_network_finalize_cost_evidence(current_setting('test.proof')::uuid,128);
select public.test_error($q$select public.partner_network_cost_statement('profit-o1','publish','{"summary":"Reviewed costs"}')$q$,'cost_statement_content_review_required');
select public.partner_network_cost_statement('profit-o1','publish',jsonb_build_object('summary','All reviewed costs included; this redacted statement approved for this partner only','evidence_id',current_setting('test.proof'),'content_reviewed',true,'expected_snapshot',(public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->'preview_snapshot')-'order_id'));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert((public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->>'available')::boolean and (public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->'snapshot'->>'internal_cost_total')::numeric=600000,'explicit reviewed publication grants ownpartner safe statement');
select public.test_assert(not(public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid) ? 'preview_snapshot') and not(public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->'evidence' ? 'storage_path'),'partner DTO has no manager preview or raw file path');
select public.test_assert(public.partner_network_cost_evidence_access(current_setting('test.proof')::uuid)->>'id'=current_setting('test.proof'),'ownpartner can access only selected released proof through broker');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',false);
select public.test_error(format('select public.partner_network_cost_statement_view(%L)',current_setting('test.profit_c1')),'cost_statement_not_available');
