select public.test_assert((public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->>'available')::boolean=false,'withdraw stops new partner access');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.partner_network_cost_statement('profit-o1','publish',jsonb_build_object('summary','Redacted statement republished after check','evidence_id',current_setting('test.proof'),'content_reviewed',true,'expected_snapshot',(public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->'preview_snapshot')-'order_id'));
select set_config('test.seen_snapshot',((public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->'preview_snapshot')-'order_id')::text,false);
