select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert((public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->>'available')::boolean=false,'adjustment invalidates released calculation/proof access');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.partner_network_reconcile('profit-o1','{"vat_amount":100000,"billed_shipping_amount":50000,"refunded_amount":50000,"internal_cost_total":700000,"minimum_retained_profit":0,"review_note":"Corrected actualcosts before payment"}');
select public.test_error(format('select public.partner_network_cost_statement(''profit-o1'',''publish'',%L)',jsonb_build_object('summary','Unseen changedcosts must not publish','content_reviewed',true,'expected_snapshot',current_setting('test.seen_snapshot')::jsonb)::text),'cost_statement_preview_changed');
select public.test_assert((public.partner_network_cost_statement_view(current_setting('test.profit_c1')::uuid)->'preview_snapshot'->>'internal_cost_total')::numeric=700000,'stale published statement has current manager preview for deliberate republish');
