select public.partner_network_reconcile('profit-o1','{"vat_amount":100000,"billed_shipping_amount":50000,"refunded_amount":50000,"internal_cost_total":750000,"minimum_retained_profit":0,"review_note":"Later corrected actualcosts flag historical settlement"}');
select public.test_assert((select to_jsonb(c)=current_setting('test.paidprofit')::jsonb from public.partner_network_commissions c where id=current_setting('test.profit_c1')::uuid),'paidprofit ledger remains immutable after cost correction');
select public.test_assert((select (c->>'overpaid_amount')::numeric=1500 from jsonb_array_elements(public.partner_network_admin_snapshot()->'commissions') c where c->>'id'=current_setting('test.profit_c1')),'later actualcost correction flags overpaid amount without rewritinghistory');
reset role;
select public.test_assert(not has_function_privilege('authenticated','public.partner_network_manage_partner_revenue_v1(uuid,text,jsonb)','execute') and not has_function_privilege('authenticated','public.partner_network_snapshot_revenue_v1()','execute'),'private legacy helpers cannot bypass current authorization');
select public.test_assert(not has_function_privilege('anon','public.partner_network_cost_evidence_access(uuid)','execute') and not has_table_privilege('authenticated','public.partner_network_cost_statements','update'),'anon proof access and direct authenticated publication mutation denied');
